SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='9e4735c7-aaf3-516f-8347-db864692cbb9'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('d0c2ba1a-5398-5930-a7e1-83adba881e68','8e5dc18a-d567-50f0-8632-a1deaee38f77')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='9e4735c7-aaf3-516f-8347-db864692cbb9'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='9e4735c7-aaf3-516f-8347-db864692cbb9'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('d0c2ba1a-5398-5930-a7e1-83adba881e68','8e5dc18a-d567-50f0-8632-a1deaee38f77')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='9e4735c7-aaf3-516f-8347-db864692cbb9'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='d0c2ba1a-5398-5930-a7e1-83adba881e68' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-00-valid' AND q.fingerprint='d796e70ebdf90ff13fd7692da678e7919f417fb53b8d1c745868b2773bf18ed3'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-00-valid","status":"ok","value":{"customerProfileId":"9e4735c7-aaf3-516f-8347-db864692cbb9","userId":"f4d646ef-4ed8-55eb-b415-aa64917bc984","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"d0c2ba1a-5398-5930-a7e1-83adba881e68","semanticKey":"customer-controls-customer-00-valid","fingerprint":"d796e70ebdf90ff13fd7692da678e7919f417fb53b8d1c745868b2773bf18ed3","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='4a29d984-b9b1-57fb-aad7-36c7b9479925' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='05537f89-9c03-5c0c-919f-29c99d5fa49a' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"9e4735c7-aaf3-516f-8347-db864692cbb9"},"prior":null,"committed":{"id":"9e4735c7-aaf3-516f-8347-db864692cbb9","userId":"f4d646ef-4ed8-55eb-b415-aa64917bc984","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='9e4735c7-aaf3-516f-8347-db864692cbb9' AND c.user_id='f4d646ef-4ed8-55eb-b415-aa64917bc984' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-00-valid' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='f82eff0f-9dc9-584b-a315-2874392cf22d' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"9e4735c7-aaf3-516f-8347-db864692cbb9","userId":"f4d646ef-4ed8-55eb-b415-aa64917bc984","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='a6df3fda-a18d-5c0b-8590-319fa86c454a' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"f4d646ef-4ed8-55eb-b415-aa64917bc984","track":"customer","customerProfileId":"9e4735c7-aaf3-516f-8347-db864692cbb9","sourceCreationRevision":"0","sourceCreationReceipt":"d0c2ba1a-5398-5930-a7e1-83adba881e68","semanticKey":"customer_buyer_profile/9e4735c7-aaf3-516f-8347-db864692cbb9/default-free-enrollment/v1"}'::jsonb)))=2));
